#!/usr/bin/env python3
"""Writes docs/COST_ANALYSIS.md from the same cost model the API serves, so the document can never drift from the engine.
    python scripts/cost_report.py [bronze silver gold]   (tenant mix; default 4 2 0)"""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from app.services.platform import engine
mix = dict(zip(("bronze", "silver", "gold"), map(int, sys.argv[1:4]))) if len(sys.argv) >= 4 else {"bronze": 4, "silver": 2, "gold": 0}
m = engine.cost_model(mix); cm = m["assumptions"]; inr = lambda v: f"₹{round(v):,}"
L = ["# Cost analysis — uniAIverse platform (v2.6)", "", f"*Generated by `scripts/cost_report.py` from `app/services/platform/content/cost_model.yaml` and `plans.yaml` (version {cm['version']}, reviewed {cm['last_reviewed']}). {m['status']}*", "",
     "## 1. Fixed monthly cost — what uniAIverse pays whether or not anyone buys", "", "| Line | ₹/month | Note |", "|---|---:|---|"]
L += [f"| {k.replace('_', ' ')} | {inr(v['inr'])} | {v['note']} |" for k, v in cm["fixed"].items()] + [f"| **Total fixed** | **{inr(m['fixed_monthly_inr'])}** | includes the ₹{cm['fixed']['free_sandbox_pool']['inr']:,} free-sandbox cap |", ""]
L += ["## 2. Per-tenant unit economics — one tenant at full quota", "", "| Plan | Platform fee | Infra billed (cost + 15%) | Monthly revenue | Monthly cost to us | Payment fees | Gross margin | Margin % | Cost / query | Revenue / query |", "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
L += [f"| {k.title()} | {inr(p['platform_fee_inr'])} | {inr(p['infra_billed_inr'])} | {inr(p['monthly_revenue_inr'])} | {inr(p['monthly_cost_inr'])} | {inr(p['payment_fees_inr'])} | **{inr(p['gross_margin_inr'])}** | {p['gross_margin_pct']}% | ₹{p['cost_per_query_inr']} | ₹{p['revenue_per_query_inr']} |" for k, p in m["plans"].items()]
L += ["", "Cost lines per tenant (₹/month):", "", "| Line | " + " | ".join(k.title() for k in m["plans"]) + " |", "|---|" + "---:|" * len(m["plans"])]
lines = sorted({l for p in m["plans"].values() for l in p["cost_lines"]}); L += [f"| {l} | " + " | ".join(inr(p["cost_lines"].get(l, 0)) for p in m["plans"].values()) + " |" for l in lines]
L += ["", "Notes on the lines: " + "; ".join(f"**{k}** {v['note']}" for k, v in cm["per_tenant"]["silver"].items()) + ".", "", f"Setup fees (one-time): " + ", ".join(f"{k.title()} {inr(p['setup_fee_inr'])}" for k, p in m["plans"].items()) + ".", ""]
L += ["## 3. Break-even", "", "Tenants of ONE plan needed to cover the fixed cost from gross margin:", "", "| Plan | Tenants to break even |", "|---|---:|"] + [f"| {k.title()} | {v} |" for k, v in m["break_even_tenants"].items()]
mo = m["monthly"]; L += ["", f"## 4. P&L at a mix of {', '.join(f'{n} {k.title()}' for k, n in m['mix'].items())}", "", "| Line | ₹/month |", "|---|---:|", f"| Revenue | {inr(mo['revenue'])} |", f"| Cost of tenants | −{inr(mo['cost_of_tenants'])} |", f"| Fixed | −{inr(mo['fixed'])} |", f"| Payment fees | −{inr(mo['payment_fees'])} |", f"| **Operating result** | **{inr(mo['operating_result'])}** |", f"| One-time setup fees at this mix | +{inr(mo['one_time_setup_fees'])} |", f"| Founder time, NOT included above | ({inr(mo['founder_time_inr_not_included'])}) |", ""]
L += ["## 5. Free sandbox", "", f"Cap {inr(m['free_sandbox']['monthly_cap_inr'])}/month, {m['free_sandbox']['queries']:,} queries, at most {m['free_sandbox']['max_users']} approved users. When the pool is spent the API answers `FREE CAPACITY EXHAUSTED` and approvals stop. Anonymous website demos draw from the same pool. This is the entire exposure of the free tier: it cannot exceed the cap.", ""]
s = m["sensitivity"]; L += ["## 6. Sensitivity", "", "| Scenario | " + " | ".join(k.title() for k in m["plans"]) + " |", "|---|" + "---:|" * len(m["plans"]), "| Gross margin as modelled | " + " | ".join(inr(p["gross_margin_inr"]) for p in m["plans"].values()) + " |",
      "| LLM prices double | " + " | ".join(inr(s["llm_price_x2"][k]) for k in m["plans"]) + " |", "| Tenant uses half its quota | " + " | ".join(inr(s["half_quota_used"][k]) for k in m["plans"]) + " |", f"| Gold with a ₹75,000 GPU line | — | — | {inr(s['gold_with_gpu_75k'])} |", "",
      "Reading it: margins survive a doubling of LLM prices because infrastructure is passed through at cost + 15% and LLM spend is capped per tenant by `monthly_spend_limit_inr`. The biggest lever is support hours, which is the one line that scales with people, not servers.", "",
      "## 7. Deployment options and their cost", "", "| Option | Control plane | Customer environments | ₹/month at launch | When |", "|---|---|---|---:|---|",
      "| A. Launch (now) | one VPS + Cloudflare | Bronze slices on one customer host; Silver/Gold as generated compose files on a VPS each | " + inr(m["fixed_monthly_inr"]) + " + per tenant | Until the second Silver |",
      "| B. Managed PaaS | Railway/Render/Fly | same, as separate services | ≈ +₹2,000–5,000 | When nobody wants to run a server |", "| C. Redundant | 2 API nodes + LB, managed Postgres | dedicated VMs | ≈ +₹6,000–12,000 | When paying customers depend on it |", "| D. India-resident / customer cloud / on-prem | AWS Mumbai or the customer's account | in the customer's account, billed to them | ≈ ₹10,000–20,000 for us; customer pays theirs | Enterprise and regulated |", "",
      "## 8. How to change any number", "", "Edit `app/services/platform/content/cost_model.yaml` (rate card) or `plans.yaml` (fees, quotas), then run `python scripts/cost_report.py` to regenerate this file, and `pytest -q` (the model must still add up)."]
out = pathlib.Path(__file__).resolve().parents[1] / "docs" / "COST_ANALYSIS.md"; out.write_text("\n".join(L) + "\n"); print(f"wrote {out} — fixed {inr(m['fixed_monthly_inr'])}/month, operating result at mix {inr(mo['operating_result'])}/month")
